(function(){
  'use strict';

  let financialCache=null;
  let financialKey=null;
  let financialSalt=null;
  const ITERATIONS=250000;
  const enc=new TextEncoder(),dec=new TextDecoder();
  const e=v=>typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=v=>Number(v)||0;
  const fmtHours=n=>`${Math.round(num(n)*10)/10}h`;
  const p=()=>state.planning||(state.planning={budget:{currency:'CAD',lines:[]},timeEntries:[]});
  const publicBudget=()=>p().budget||(p().budget={currency:'CAD',lines:[]});
  const entries=()=>p().timeEntries||(p().timeEntries=[]);
  const taskList=()=>state.tasks?.tasks||[];
  const milestoneList=()=>state.milestones?.milestones||[];
  const money=(n,c='CAD')=>new Intl.NumberFormat('en-CA',{style:'currency',currency:c,maximumFractionDigits:0}).format(num(n));
  const isUnlocked=()=>!!financialCache;
  const b64=u=>{let s='';for(const x of u)s+=String.fromCharCode(x);return btoa(s)};
  const unb64=s=>Uint8Array.from(atob(s||''),c=>c.charCodeAt(0));

  function emptyFinancial(){return {currency:publicBudget().currency||'CAD',approvedBudget:'',personRates:{},lineAmounts:{}}}
  async function deriveKey(pass,salt){const material=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:ITERATIONS,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
  async function encryptVault(){if(!financialKey||!financialCache)return;const iv=crypto.getRandomValues(new Uint8Array(12)),plain=enc.encode(JSON.stringify(financialCache)),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},financialKey,plain));p().financialVault={version:1,alg:'AES-GCM',kdf:'PBKDF2-SHA256',iterations:ITERATIONS,salt:b64(financialSalt),iv:b64(iv),ciphertext:b64(cipher),updatedAt:new Date().toISOString()};mark('planning')}
  async function decryptVault(pass){const v=p().financialVault;if(!v?.ciphertext)throw new Error('No financial vault exists.');const salt=unb64(v.salt),key=await deriveKey(pass,salt),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(v.iv)},key,unb64(v.ciphertext));financialKey=key;financialSalt=salt;financialCache=JSON.parse(dec.decode(plain));financialCache.personRates=financialCache.personRates||{};financialCache.lineAmounts=financialCache.lineAmounts||{};return true}
  async function unlockFinancial(){
    try{
      if(!window.crypto?.subtle){alert('This browser does not support the encrypted Steering financial view.');return}
      if(p().financialVault?.ciphertext){const pass=prompt('Business Owner / Steering Committee financial view\n\nEnter the Steering financial passphrase. The passphrase is not stored in the dashboard.');if(!pass)return;await decryptVault(pass)}
      else{
        const pass=prompt('Create the Business Owner / Steering Committee financial passphrase.\n\nUse a strong passphrase and share it only with authorized Steering Committee members. It is not stored by the dashboard.');if(!pass)return;if(pass.length<10){alert('Use a passphrase of at least 10 characters.');return}const confirmPass=prompt('Confirm the Steering financial passphrase.');if(pass!==confirmPass){alert('Passphrases do not match.');return}financialSalt=crypto.getRandomValues(new Uint8Array(16));financialKey=await deriveKey(pass,financialSalt);financialCache=emptyFinancial();await encryptVault();
      }
      render();
    }catch(err){financialCache=null;financialKey=null;financialSalt=null;alert('Financial view could not be unlocked. Check the passphrase and try again.');console.warn('[V28] unlock failed',err)}
  }
  function lockFinancial(){financialCache=null;financialKey=null;financialSalt=null;render()}

  function rateFor(name){return num(financialCache?.personRates?.[name])}
  function lineAmount(id,field){return num(financialCache?.lineAmounts?.[id]?.[field])}
  function plannedHours(){return taskList().reduce((s,t)=>s+num(t.estimatedHours),0)}
  function loggedHours(){return entries().reduce((s,x)=>s+num(x.hours),0)}
  function outputs(){return entries().filter(x=>String(x.output||'').trim()).length}
  function actualHoursForTask(id){return entries().filter(x=>x.taskId===id).reduce((s,x)=>s+num(x.hours),0)}
  function actualHoursForPerson(name){return entries().filter(x=>x.person===name).reduce((s,x)=>s+num(x.hours),0)}
  function plannedLaborCost(){return taskList().reduce((s,t)=>s+num(t.estimatedHours)*rateFor(t.owner),0)}
  function actualLaborCost(){return entries().reduce((s,x)=>s+num(x.hours)*rateFor(x.person),0)}
  function manualTotal(field){return (publicBudget().lines||[]).reduce((s,x)=>s+lineAmount(x.id,field),0)}
  function missingRates(){return [...new Set([...taskList().filter(t=>num(t.estimatedHours)>0).map(t=>t.owner),...entries().filter(x=>num(x.hours)>0).map(x=>x.person)].filter(Boolean))].filter(x=>!rateFor(x))}
  function planTarget(){return p().readinessTarget||'2027-12-22'}

  function hoursKpis(){const remaining=Math.max(0,plannedHours()-loggedHours()),out=outputs(),hpo=out?loggedHours()/out:0;return `<div class="v28-kpis"><div class="card"><span>Readiness target</span><b>${e(planTarget())}</b><small>business readiness baseline</small></div><div class="card"><span>Planned effort</span><b>${fmtHours(plannedHours())}</b><small>task estimates</small></div><div class="card"><span>Actual logged</span><b>${fmtHours(loggedHours())}</b><small>weekly actual hours</small></div><div class="card"><span>Remaining vs plan</span><b>${fmtHours(remaining)}</b><small>planning indicator</small></div><div class="card"><span>Outputs documented</span><b>${out}</b><small>weekly results recorded</small></div><div class="card"><span>Hours / output</span><b>${out?fmtHours(hpo):'—'}</b><small>effort-to-output indicator</small></div></div>`}
  function financialKpis(){if(!isUnlocked())return '';const f=financialCache,c=f.currency||publicBudget().currency||'CAD',missing=missingRates(),forecast=manualTotal('forecast')+plannedLaborCost(),actual=manualTotal('actual')+actualLaborCost();return `<div class="v28-financial-kpis"><div class="card"><span>Approved budget</span><b>${f.approvedBudget!==''?money(f.approvedBudget,c):'Not entered'}</b></div><div class="card"><span>Manual budget lines</span><b>${money(manualTotal('budget'),c)}</b></div><div class="card"><span>Forecast economic cost</span><b>${missing.length?'Rates incomplete':money(forecast,c)}</b><small>${missing.length?`${missing.length} loaded rate${missing.length===1?'':'s'} missing`:'manual forecast + planned internal effort'}</small></div><div class="card"><span>Actual economic cost</span><b>${missing.length?'Rates incomplete':money(actual,c)}</b><small>manual actual + logged internal effort</small></div></div>`}

  function weeklySummary(){const map=new Map();entries().forEach(x=>{const k=x.weekStart||'';const r=map.get(k)||{week:k,hours:0,people:new Set(),outputs:0};r.hours+=num(x.hours);r.people.add(x.person);if(String(x.output||'').trim())r.outputs++;map.set(k,r)});const rows=[...map.values()].sort((a,b)=>String(b.week).localeCompare(String(a.week)));return `<div class="v28-week-grid">${rows.slice(0,12).map(r=>`<div class="card"><span>Week of ${e(r.week)}</span><b>${fmtHours(r.hours)}</b><small>${r.people.size} contributor${r.people.size===1?'':'s'} · ${r.outputs} documented output${r.outputs===1?'':'s'}</small></div>`).join('')||'<div class="card empty">No weekly hours have been logged yet.</div>'}</div>`}
  function taskTable(){const rows=taskList().filter(t=>num(t.estimatedHours)>0||actualHoursForTask(t.id)>0).slice().sort((a,b)=>String(a.milestoneId||'').localeCompare(String(b.milestoneId||''))||String(a.stream||'').localeCompare(String(b.stream||'')));return `<div class="v28-table-wrap"><table class="v28-table"><thead><tr><th>Task / expected output</th><th>Milestone</th><th>Stream</th><th>Owner</th><th>Estimated</th><th>Actual</th><th>Progress</th><th>Effort used</th></tr></thead><tbody>${rows.map(t=>{const est=num(t.estimatedHours),act=actualHoursForTask(t.id),r=est?100*act/est:0,prog=typeof taskProgress==='function'?taskProgress(t):num(t.progress);return `<tr data-edit-task="${e(t.id)}"><td><b>${e(t.title)}</b><small>${e(t.expectedOutcome||'Expected outcome not documented')}</small></td><td>${e(t.milestoneId||'—')}</td><td>${e(t.stream||'Program')}</td><td>${e(t.owner||'Unassigned')}</td><td>${fmtHours(est)}</td><td><b>${fmtHours(act)}</b></td><td>${Math.round(num(prog))}%</td><td>${est?`${Math.round(r)}%`:'—'}</td></tr>`}).join('')}</tbody></table></div>`}
  function milestoneTable(){const rows=milestoneList().map(m=>{const mt=taskList().filter(t=>t.milestoneId===m.id),est=mt.reduce((s,t)=>s+num(t.estimatedHours),0),act=mt.reduce((s,t)=>s+actualHoursForTask(t.id),0);return {m,est,act,count:mt.length}});return `<div class="v28-table-wrap"><table class="v28-table"><thead><tr><th>Milestone</th><th>Dates</th><th>Tasks</th><th>Planned hours</th><th>Actual hours</th><th>Readiness signal</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${e(x.m.id)} · ${e(x.m.name)}</b></td><td>${e(x.m.start||'')} → ${e(x.m.end||'')}</td><td>${x.count}</td><td>${fmtHours(x.est)}</td><td><b>${fmtHours(x.act)}</b></td><td>${x.m.end&&x.m.end<=planTarget()?'Supports Dec-2027 readiness':'Post-readiness / go-live'}</td></tr>`).join('')}</tbody></table></div>`}
  function timeTable(){const rows=entries().slice().sort((a,b)=>String(b.weekStart||'').localeCompare(String(a.weekStart||''))||String(a.person||'').localeCompare(String(b.person||'')));return `<div class="v28-table-wrap"><table class="v28-table"><thead><tr><th>Week</th><th>Person</th><th>Task</th><th>Stream</th><th>Hours</th><th>Output received</th><th>Notes</th></tr></thead><tbody>${rows.map(x=>{const t=taskList().find(t=>t.id===x.taskId);return `<tr data-v27-time="${e(x.id)}"><td>${e(x.weekStart)}</td><td><b>${e(x.person)}</b></td><td>${x.taskId?`<b>${e(x.taskId)}</b><small>${e(t?.title||'')}</small>`:'Program / admin'}</td><td>${e(x.stream||t?.stream||'Program')}</td><td><b>${fmtHours(x.hours)}</b></td><td>${e(x.output||'')}</td><td>${e(x.notes||'')}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No time entries yet.</td></tr>'}</tbody></table></div>`}

  function budgetTable(){if(!isUnlocked())return `<div class="card pad v28-locked"><div><span>FINANCIAL VALUES RESTRICTED</span><h3>Hours-only view</h3><p>Dollar budget values, loaded hourly rates and internal effort cost are masked. Only the Business Owner and Steering Committee should unlock the financial view.</p></div><button class="btn primary" id="v28Unlock">Unlock Steering $ view</button></div>`;const c=financialCache.currency||publicBudget().currency||'CAD';return `<div class="v28-table-wrap"><table class="v28-table"><thead><tr><th>Category</th><th>Budget</th><th>Forecast</th><th>Actual</th><th>Owner</th><th>Notes</th></tr></thead><tbody>${(publicBudget().lines||[]).map(x=>`<tr data-v28-line="${e(x.id)}"><td><b>${e(x.category)}</b><small>${e(x.id)}</small></td><td>${money(lineAmount(x.id,'budget'),c)}</td><td>${money(lineAmount(x.id,'forecast'),c)}</td><td>${money(lineAmount(x.id,'actual'),c)}</td><td>${e(x.owner||'')}</td><td>${e(x.notes||'')}</td></tr>`).join('')}</tbody><tfoot><tr><th>Total</th><th>${money(manualTotal('budget'),c)}</th><th>${money(manualTotal('forecast'),c)}</th><th>${money(manualTotal('actual'),c)}</th><th></th><th></th></tr></tfoot></table></div>`}
  function rateTable(){if(!isUnlocked())return '';const c=financialCache.currency||publicBudget().currency||'CAD',names=[...new Set([state.framework?.businessOwner?.name||'Alex',...(state.framework?.people||[]).map(x=>x.name),...taskList().map(t=>t.owner)].filter(Boolean))].sort();return `<div class="v28-table-wrap"><table class="v28-table"><thead><tr><th>Person</th><th>Role / stream</th><th>Loaded rate</th><th>Planned hours</th><th>Actual hours</th><th>Planned internal cost</th><th>Actual internal cost</th></tr></thead><tbody>${names.map(name=>{const pr=(state.framework?.people||[]).find(x=>x.name===name),rate=rateFor(name),ph=taskList().filter(t=>t.owner===name).reduce((s,t)=>s+num(t.estimatedHours),0),ah=actualHoursForPerson(name);return `<tr><td><b>${e(name)}</b></td><td>${e(pr?.role||'Business Owner')}<small>${e(pr?.stream||'Program')}</small></td><td>${rate?`${money(rate,c)}/h`:'Not entered'}</td><td>${fmtHours(ph)}</td><td>${fmtHours(ah)}</td><td>${rate?money(rate*ph,c):'—'}</td><td>${rate?money(rate*ah,c):'—'}</td></tr>`}).join('')}</tbody></table></div>`}

  function renderPrivateBudget(){const unlocked=isUnlocked();return `<div class="v28-budget"><div class="page-head"><div><h1>Budget & Effort Control</h1><p>${unlocked?'Steering financial view is unlocked for this browser session.':'Default team view: effort is shown in hours; dollar values are masked.'}</p></div><div class="button-row">${unlocked?'<button class="btn" id="v28FinancialSettings">Financial settings</button><button class="btn" id="v28Lock">Lock $ view</button>':'<button class="btn" id="v28Unlock">Unlock Steering $ view</button>'}<button class="btn" id="v27ExportTime">Export time CSV</button><button class="btn primary" id="v27LogTime">+ Log weekly hours</button></div></div><div class="notice v28-privacy"><b>Audience rule:</b> Business Owner + Steering Committee may use the encrypted dollar view. All other users see hours only. Because this Control Tower is deployed as static GitHub Pages without identity authentication, authorization is enforced with the Steering financial passphrase; the passphrase itself is never stored.</div>${hoursKpis()}${financialKpis()}<div class="section-title"><h2>Weekly effort</h2><span>actual hours and outputs received</span></div>${weeklySummary()}<div class="section-title"><h2>Time log</h2><span>hours remain visible to the project team</span></div>${timeTable()}<div class="section-title"><h2>Effort by task and output</h2><span>planned versus actual hours</span></div>${taskTable()}<div class="section-title"><h2>Effort by milestone</h2><span>December 2027 readiness work</span></div>${milestoneTable()}<div class="section-title"><h2>Project budget</h2><span>${unlocked?'Steering financial view':'financial amounts masked'}</span></div>${budgetTable()}${unlocked?`<div class="section-title"><h2>Internal effort valuation</h2><span>Steering financial view</span></div>${rateTable()}`:''}</div>`}

  function financialNames(){return [...new Set([state.framework?.businessOwner?.name||'Alex',...(state.framework?.people||[]).map(x=>x.name),...taskList().map(t=>t.owner)].filter(Boolean))].sort()}
  function editFinancialSettings(){if(!isUnlocked())return unlockFinancial();const f=financialCache,c=f.currency||publicBudget().currency||'CAD';const m=modal('Steering financial settings',`<div class="form-grid"><label>Currency<input name="currency" value="${e(c)}"></label><label>Approved project budget<input type="number" min="0" step="1000" name="approvedBudget" value="${e(f.approvedBudget||'')}"></label></div><div class="section-title"><h2>Loaded hourly rates</h2><span>encrypted financial data</span></div><div class="v28-rate-editor">${financialNames().map(name=>`<label><span><b>${e(name)}</b><small>${e((state.framework?.people||[]).find(x=>x.name===name)?.role||'Business Owner')}</small></span><input type="number" min="0" step="1" data-v28-rate="${e(name)}" value="${e(f.personRates?.[name]||'')}" placeholder="$/h"></label>`).join('')}</div><div class="notice"><b>Privacy:</b> dollar values are encrypted before they are written to the shared planning file. The passphrase is not written to GitHub.</div>`);m.querySelector('.modal-save').onclick=async()=>{const v=vals(m);f.currency=v.currency||'CAD';f.approvedBudget=v.approvedBudget;f.personRates=f.personRates||{};m.querySelectorAll('[data-v28-rate]').forEach(x=>{const val=num(x.value),name=x.dataset.v28Rate;if(val>0)f.personRates[name]=val;else delete f.personRates[name]});await encryptVault();m.remove();render()}}
  function editLine(id){if(!isUnlocked())return;const meta=(publicBudget().lines||[]).find(x=>x.id===id);if(!meta)return;const f=financialCache;f.lineAmounts=f.lineAmounts||{};const z=f.lineAmounts[id]||(f.lineAmounts[id]={budget:'',forecast:'',actual:''});const m=modal(`Steering budget · ${meta.category}`,`<div class="form-grid"><label>Budget<input type="number" min="0" step="1000" name="budget" value="${e(z.budget||'')}"></label><label>Forecast<input type="number" min="0" step="1000" name="forecast" value="${e(z.forecast||'')}"></label><label>Actual<input type="number" min="0" step="1000" name="actual" value="${e(z.actual||'')}"></label><label class="full">Category<input value="${e(meta.category)}" disabled></label></div>`);m.querySelector('.modal-save').onclick=async()=>{Object.assign(z,vals(m));await encryptVault();m.remove();render()}}

  function pulse(){return `<section class="v28-pulse"><div class="section-title"><div><h2>Effort pulse</h2><span>planned effort → actual hours → output received</span></div><button class="btn" type="button" data-v28-open-budget>Open Budget & Effort</button></div><div class="v28-pulse-grid"><div class="card"><span>Planned effort</span><b>${fmtHours(plannedHours())}</b></div><div class="card"><span>Actual logged</span><b>${fmtHours(loggedHours())}</b></div><div class="card"><span>Outputs logged</span><b>${outputs()}</b></div><div class="card"><span>Financial view</span><b>${isUnlocked()?'Steering unlocked':'Hours only'}</b></div></div></section>`}

  if(typeof renderCockpit==='function'){const prev=renderCockpit;renderCockpit=function(){let out=prev();out=out.replace(/<section class="v27-pulse">[\s\S]*?<\/section>/,'');return out+pulse()}}
  if(typeof renderBusinessOwner==='function'){const prev=renderBusinessOwner;renderBusinessOwner=function(){let out=prev();out=out.replace(/<section class="v27-pulse">[\s\S]*?<\/section>/,'');return out+pulse()}}

  const prevBind=bindPage;
  bindPage=function(){prevBind();document.querySelectorAll('[data-v28-open-budget]').forEach(x=>x.onclick=()=>{view='budget';document.querySelectorAll('#mainNav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='budget'));render()});document.querySelectorAll('#v28Unlock').forEach(x=>x.onclick=unlockFinancial);$('#v28Lock')?.addEventListener('click',lockFinancial);$('#v28FinancialSettings')?.addEventListener('click',editFinancialSettings);document.querySelectorAll('[data-v28-line]').forEach(x=>x.onclick=()=>editLine(x.dataset.v28Line))};

  const prevRender=render;
  render=function(){if(view==='budget'){const app=$('#app');app.innerHTML=renderPrivateBudget();bindPage();return}prevRender()};
  window.D365_FINANCIAL_PRIVACY={unlock:unlockFinancial,lock:lockFinancial,isUnlocked};
})();
